s = s.replace("name: 'More Settings'", "name: /^Settings for/ ")
s = s.replace("name: 'Configure advancement'", "name: 'Advancement & Elimination'")
s = s.replace("name: 'Configure progression'", "name: 'Next Round / Back to Zero'")
